      AppLesson(
        title: "Add Flutter Screen",
        body: "title: Add a Flutter screen to an macOS app\nshortTitle: Add a Flutter screen\ndescription: Learn how to add a single Flutter screen to your existing macOS app.\n\nThis guide describes how to add a single Flutter screen to an existing macOS app.\nStart a FlutterEngine and FlutterViewController\n\nTo launch a Flutter screen from an existing macOS app,\nyou start a [FlutterEngine][] and a [FlutterViewController][].\n\n:::note\nThe FlutterEngine serves as a host to the Dart VM and your Flutter runtime,\nand the FlutterViewController attaches to a FlutterEngine\nto pass input events into Flutter\nand to display frames rendered by the FlutterEngine.\n:::\n\nThe FlutterEngine might have the same lifespan\nas your FlutterViewController or outlive your FlutterViewController.\n\n:::tip\nIt's generally recommended to pre-warm a long-lived\nFlutterEngine for your application because:\n\n The first frame appears faster when showing the FlutterViewController.\n Your Flutter and Dart state will outlive one FlutterViewController.\nYour application and your plugins can interact with Flutter\n  and your Dart logic before showing the UI.\n:::\n\nSee [Loading sequence and performance][]\nfor more analysis on the latency and memory\ntrade-offs of pre-warming an engine.\nCreate a FlutterEngine\n\nWhere you create a FlutterEngine depends on your host app.\n\nIn this example, we create a FlutterEngine object\ninside a SwiftUI [Observable][] object called FlutterDependencies.\nPre-warm the engine by calling run(), and then inject this object\ninto a ContentView using the environment() view modifier.\n\n swift title=\"MyApp.swift\"\nimport SwiftUI\nimport FlutterMacOS\n// The following library connects plugins with macOS platform code to this app.\nimport FlutterPluginRegistrant\n\n@Observable\nclass FlutterDependencies {\n  let flutterEngine = FlutterEngine(name: \"my flutter engine\", project: nil)\n  init() {\n    // Runs the default Dart entrypoint with a default Flutter route.\n    flutterEngine.run(withEntrypoint: nil)\n    // Connects plugins with macOS platform code to this app.\n    RegisterGeneratedPlugins(registry: self.flutterEngine)\n  }\n}\n\n@main\nstruct MyApp: App {\n    // flutterDependencies will be injected through the view environment.\n    @State var flutterDependencies = FlutterDependencies()\n    var body: some Scene {\n      WindowGroup {\n        ContentView()\n          .environment(flutterDependencies)\n      }\n    }\n}\nswift title=\"AppDelegate.swift\"\nimport Cocoa\nimport FlutterMacOS\n// The following library connects plugins with macOS platform code to this app.\nimport FlutterPluginRegistrant\n\n@main\nclass AppDelegate: FlutterAppDelegate {\n  lazy var flutterEngine = FlutterEngine(name: \"my flutter engine\", project: nil)\n\n  override func applicationDidFinishLaunching( aNotification: Notification) {\n    flutterEngine.run(withEntrypoint: nil)\n    RegisterGeneratedPlugins(registry: self.flutterEngine)\n  }\n}\nswift title=\"ContentView.swift\"\nimport SwiftUI\nimport FlutterMacOS\n\nstruct FlutterViewControllerRepresentable: NSViewControllerRepresentable {\n  // Flutter dependencies are passed in through the view environment.\n  @Environment(FlutterDependencies.self) var flutterDependencies\n\n  func makeNSViewController(context: Context) -> FlutterViewController {\n    return FlutterViewController(\n      engine: flutterDependencies.flutterEngine,\n      nibName: nil,\n      bundle: nil\n    )\n  }\n\n  func updateNSViewController( nsViewController: FlutterViewController, context: Context) {}\n}\n\nstruct ContentView: View {\n  var body: some View {\n    NavigationStack {\n      NavigationLink(\"My Flutter Feature\") {\n        FlutterViewControllerRepresentable()\n      }\n    }\n  }\n}\nswift title=\"ViewController.swift\"\nimport Cocoa\nimport FlutterMacOS\n\nclass ViewController: NSViewController {\n\n  override func viewDidLoad() {\n    super.viewDidLoad()\n\n    // Make a button to call the showFlutter function when pressed.\n    let button =  NSButton(title: \"Show Flutter!\", target: self, action: #selector(showFlutter))\n    button.frame = CGRect(x: 202, y: 187, width: 160.0, height: 40.0)\n    self.view.addSubview(button)\n  }\n\n  @objc func showFlutter() {\n    let flutterEngine = (NSApplication.shared.delegate as! AppDelegate).flutterEngine\n    let flutterViewController =\n        FlutterViewController(engine: flutterEngine, nibName: nil, bundle: nil)\n    self.addChild(flutterViewController)\n    flutterViewController.view.frame = self.view.bounds\n    presentAsModalWindow(flutterViewController)\n  }\n}\nswift title=\"ContentView.swift\"\n// Existing code omitted.\nfunc makeNSViewController(context: Context) -> FlutterViewController {\n  return FlutterViewController()\n}\nswift title=\"ViewController.swift\"\n// Existing code omitted.\nfunc showFlutter() {\n  let flutterViewController = FlutterViewController()\n  self.addChild(flutterViewController)\n  flutterViewController.view.frame = self.view.bounds\n  presentAsModalWindow(flutterViewController)\n}\nswift title=\"MyApp.swift\"\nimport SwiftUI\nimport FlutterMacOS\n\n@Observable\nclass AppDelegate: FlutterAppDelegate {\n  let flutterEngine = FlutterEngine(name: \"my flutter engine\", project: nil)\n\n  override func applicationDidFinishLaunching( aNotification: Notification) {\n    // Runs the default Dart entrypoint with a default Flutter route.\n    flutterEngine.run(withEntrypoint: nil)\n    // Used to connect plugins (only if you have plugins\n    // with macOS platform code).\n    RegisterGeneratedPlugins(registry: self.flutterEngine)\n  }\n}\n\n@main\nstruct MyApp: App {\n  // Use this property wrapper to tell SwiftUI\n  // it should use the AppDelegate class for the application delegate\n  @NSApplicationDelegateAdaptor(AppDelegate.self) var appDelegate\n\n  var body: some Scene {\n    WindowGroup {\n      ContentView()\n    }\n  }\n}\nswift title=\"ContentView.swift\"\nimport SwiftUI\nimport FlutterMacOS\n\nstruct FlutterViewControllerRepresentable: NSViewControllerRepresentable {\n  // Access the AppDelegate through the view environment.\n  @Environment(AppDelegate.self) var appDelegate\n\n  func makeNSViewController(context: Context) -> FlutterViewController {\n    return FlutterViewController(\n      engine: appDelegate.flutterEngine,\n      nibName: nil,\n      bundle: nil\n    )\n  }\n\n  func updateNSViewController( nsViewController: FlutterViewController, context: Context) {}\n}\n\nstruct ContentView: View {\n  var body: some View {\n    NavigationStack {\n      NavigationLink(\"My Flutter Feature\") {\n        FlutterViewControllerRepresentable()\n      }\n    }\n  }\n}",
        codeSnippet: "</Tab>\n<Tab name=\"AppKit-Swift\">\n\nAs an example, we demonstrate creating a `FlutterEngine`,\nexposed as a property, on app startup in the app delegate.\n\n</Tab>\n</Tabs>\n\n### Show a FlutterViewController with your FlutterEngine\n\n<Tabs key=\"macos-framework\">\n<Tab name=\"SwiftUI\">\n\nThe following example shows a generic `ContentView` with a\n[`NavigationLink`][] hooked to a flutter screen.\nFirst, create a `FlutterViewControllerRepresentable`\nto represent the `FlutterViewController`.\nThe `FlutterViewController` constructor takes\nthe pre-warmed `FlutterEngine` as an argument,\nwhich is injected through the view environment.\n\nNow, you have a Flutter screen embedded in your macOS app.\n\n:::note\nIn this example, your Dart `main()` entrypoint function runs\nwhen the `FlutterDependencies` observable is initialized.\n:::\n\n</Tab>\n<Tab name=\"AppKit-Swift\">\n\nThe following example shows a generic `ViewController` with an\n`NSButton` hooked to present a [`FlutterViewController`][].\nThe `FlutterViewController` uses the `FlutterEngine` instance\ncreated in the `AppDelegate`.\n\nNow, you have a Flutter screen embedded in your macOS app.\n\n:::note\nUsing the previous example, the default `main()` entrypoint function\nof your default Dart library runs\nwhen calling `run` on the `FlutterEngine` created in the `AppDelegate`.\n:::\n\n</Tab>\n</Tabs>\n\n### _Alternatively_ - Create a FlutterViewController with an implicit FlutterEngine\n\nAs an alternative to the previous example,\nyou can let the `FlutterViewController` implicitly create\nits own `FlutterEngine` without pre-warming one ahead of time.\n\nThis is not usually recommended\nbecause creating a `FlutterEngine` on-demand could introduce a noticeable\nlatency between when the `FlutterViewController` is presented\nand when it renders its first frame.\nThis could, however, be useful if the Flutter screen is rarely shown,\nwhen there are no good heuristics\nto determine when the Dart VM should be started,\nand when Flutter doesn't need to persist state between view controllers.\n\nTo let the `FlutterViewController` present without an existing `FlutterEngine`,\nomit the `FlutterEngine` construction,\nand create the `FlutterViewController` without an engine reference.\n\n<Tabs key=\"macos-framework\">\n<Tab name=\"SwiftUI\">\n\n</Tab>\n<Tab name=\"AppKit-Swift\">\n\n</Tab>\n</Tabs>\n\nSee [Loading sequence and performance][]\nfor more explorations on latency and memory usage.\n\n## Using the FlutterAppDelegate\n\nLetting your application's `UIApplicationDelegate` subclass\n`FlutterAppDelegate` is recommended but not required.\n\nThe `FlutterAppDelegate` performs functions such as:\n\n* Forwarding application callbacks such as [`openURLs`][]\n  to plugins such as [google_sign_in][].\n\n### Creating a FlutterAppDelegate subclass\n\nCreating a subclass of the `FlutterAppDelegate` in UIKit apps was shown\nin the [Start a FlutterEngine and FlutterViewController section][].\nIn a SwiftUI app, you can create a subclass of the `FlutterAppDelegate`\nand annotate it with the [`Observable()`][] macro as follows:\n\nThen, in your view, the `AppDelegate` is accessible\nthrough the view environment.",
        hasImage: false,
      ),
      AppLesson(
        title: "Project Setup",
        body: "title: Integrate a Flutter app into your macOS project\nshortTitle: Integrate Flutter\ndescription: Learn how to integrate a Flutter app into your existing macOS project.\n\n:::note\nAs of the 3.44 release, Flutter uses [Swift Package Manager][]\nto manage iOS and macOS native dependencies.\nFlutter continues to support CocoaPods in maintenance mode,\nhowever, the CocoaPods registry permanently becomes\n[read-only on December 2, 2026][cocoapods].\n:::\n\nFlutter UI components can be incrementally added\ninto your existing macOS application using Swift packages.\nPrerequisites\n\n Flutter 3.44 or later\n Xcode 15.0 or later\nMigrate from legacy integration (if applicable) {: #migrate-legacy-integration}\n\nIf you've already integrated Flutter into your macOS app\nusing embedded frameworks,\nyou must first remove that integration\nbefore following the Swift Package Manager instructions below.\n\n  Expand to see instructions to migrate from embedded frameworks integration\n\n  If your app was previously integrated using frameworks\n  generated by the flutter build macos-framework command,\n  you must first remove the frameworks from your Xcode project.\nNavigate to your target's General tab\n     and remove all Flutter-related frameworks and libraries\n     under Frameworks, Libraries, and Embedded Content.\n\n       This includes the App.xcframework, FlutterMacOS.xcframework,\n       FlutterPluginRegistrant.xcframework,\n       and any Flutter plugins' xcframework files.\nRemove the Flutter pod from your Podfile\n      ruby title=\"MyApp/Podfile\" diff\npod 'FlutterMacOS', :podspec => '/path/to/MyApp/Flutter/[build mode]/FlutterMacOS.podspec'\n      console\nflutter create my_flutter_app\nconsole\n    flutter build swift-package --platform macos\n\n       FLUTTER_SWIFT_PACKAGE_OUTPUT=\$SRCROOT/../my_flutter_app/build/macos/SwiftPackages\n\n       ENABLE_APP_SANDBOX=YES\n       ENABLE_INCOMING_NETWORK_CONNECTIONS=YES\n       RUNTIME_EXCEPTION_ALLOW_JIT=YES\n\n       FLUTTER_APPLICATION_PATH=\$SRCROOT/../my_flutter_app\n       ENABLE_USER_SCRIPT_SANDBOXING=NO\n\n       /bin/sh \$FLUTTER_SWIFT_PACKAGE_OUTPUT/Scripts/flutter_integration.sh prebuild\n\n       /bin/sh \$FLUTTER_SWIFT_PACKAGE_OUTPUT/Scripts/flutter_integration.sh assemble\n\n       \$(FLUTTER_SWIFT_PACKAGE_OUTPUT)/Scripts/FlutterAssembleInputs.xcfilelist\n\n\n\n\n{:.steps}\nNext steps\n\nYou can now [add a Flutter screen][] to your existing macOS app.",
        codeSnippet: "1. Run `pod install`.\n</details>\n\n### Organize your projects relative to each other {: #organize-projects-relatively}\n\nThis guide assumes that your existing macOS app\nand your Flutter app reside in sibling directories.\nIf you have a different directory structure,\nyou will need to adjust the example relative paths accordingly.\n\n:::note\n\nIf integrating for the first time,\nrun the following command to create a new Flutter application:\n\n:::\n\nThe example directory structure resembles the following:\n\n<FileTree>\n\n- my_flutter_app/\n  - macos/\n  - lib/\n    - main.dart\n- MyNativeApp/\n  - MyNativeApp.xcodeproj/\n\n</FileTree>\n\n## Integrate with Swift Package Manager {: #integrate-with-swiftpm}\n\n 1. <h3>Build the FlutterNativeIntegration Swift package</h3>\n\n    Within your Flutter application or module, run the following command:\n\n    \n\n    This generates the following directories:\n\n    <FileTree>\n\n    - my_flutter_app/build/macos/SwiftPackages/\n      - FlutterNativeIntegration/ (A Swift package)\n      - Scripts/ (Directory of scripts and other files needed)\n\n    </FileTree>\n\n    You can optionally change the location of this output\n    with the `--output` flag.\n\n 1. <h3>Add FlutterNativeIntegration to your Xcode project</h3>\n\n    1. In the Project navigator, right click on your project\n       and select **Add Files to \"MyNativeApp\"...**\n    1. Navigate to and select the generated\n       `FlutterNativeIntegration` Swift package and click **Add**.\n    1. Select **Reference files in place** and click **Finish**.\n    1. In the File inspector,\n       verify the **Location** is **Relative to Project**.\n       If it is not, you'll need to move the Flutter output directory\n       to be a sibling directory of your native app.\n\n       <DashImage image=\"development/add-to-app/macos/project-setup-swiftpm/flutternativeintegration-relative-location.png\" caption=\"Relative location of FlutterNativeIntegration shown in Xcode's File inspector.\" />\n\n    1. Navigate to your target's **General** tab\n       and add `FlutterNativeIntegration` under\n       **Frameworks, Libraries, and Embedded Content**.\n\n       <DashImage image=\"development/add-to-app/ios/project-setup-swiftpm/flutternativeintegration-library.png\" caption=\"FlutterNativeIntegration under Frameworks, Libraries, and Embedded Content.\" />\n\n 1. <h3>Add build settings</h3>\n\n    1. In the **Build Settings** tab,\n       set the location of the Flutter app's Swift package output directory:\n       \n\n    1. For custom configurations, set the Flutter build mode.\n\n       Flutter supports three [build modes][]: Debug, Profile, and Release.\n       The build mode is determined using the `CONFIGURATION` value.\n       If your configuration does not match one of these,\n       you can set the `FLUTTER_BUILD_MODE` build setting\n       to one of these values.\n\n       <DashImage image=\"development/add-to-app/ios/project-setup-swiftpm/flutter-build-mode.png\" caption=\"Setting `FLUTTER_BUILD_MODE` for custom configurations under **Build Settings**.\" />\n\n    1. For **Debug** configurations only, set the following build settings:\n\n       \n\n       <DashImage image=\"development/add-to-app/macos/project-setup-swiftpm/allow-jit-build-setting.png\" caption=\"Set **Allow JIT** (RUNTIME_EXCEPTION_ALLOW_JIT) to **YES** in the target's **Build Settings** for **Debug** configurations only.\" />\n\n    1. (Optional) Allow Xcode to re-build your Flutter app.\n\n       Add the following build settings to your target\n       to allow Xcode to re-build your Flutter app as part of its build.\n       This allows you to make changes to your Flutter application\n       without needing to re-run `flutter build swift-package`.\n       This requires a Flutter installation on the machine.\n\n       \n\n       :::tip\n       This only re-builds the Flutter app's code.\n       If you add new dependencies,\n       you’ll need to re-run `flutter build swift-package`.\n       :::\n\n 1. <h3>Add Pre-action Run Script to Scheme</h3>\n\n    1. Open **Product** &gt; **Scheme** &gt; **Edit Scheme...**\n       &gt; **Build** (in left side bar) &gt; **Pre-action** &gt; **+**\n       &gt; **New Run Script Action**\n\n    1. Select your project in the **Provide build settings from** dropdown.\n\n    1. Set the script to the following:\n       \n\n    <DashImage image=\"development/add-to-app/ios/project-setup-swiftpm/pre-action.png\" caption=\"Pre-action Run Script in scheme editor.\" />\n\n 1. <h3>Add new run script build phase to your target</h3>\n\n    1. Navigate to your target's **Build Phases**\n       &gt; **+** &gt; **New Run Script Phase**\n\n    1. Set the script to the following:\n       \n\n    1. Uncheck **Based on dependency analysis**\n    1. Add the following to **Input File Lists**:",
